                ?? throw new InvalidOperationException("The samples-selected signal of GstAggregator passed no segment.");
            ulong ptsValue = pts;
            ulong dtsValue = dts;
            ulong durationValue = duration;
            using Gst.Structure? infoValue = Gst.Structure.FromNative(info, Gst.Interop.Transfer.None);
            handler(
                Gst.GObject.Object.FromNative(instance, Gst.Interop.Transfer.None),
                new Gst.Base.Aggregator.SamplesSelectedSignalArgs(segmentValue, ptsValue, dtsValue, durationValue, infoValue));
        }
        catch (Exception exception)
        {
            Gst.Interop.ExceptionTrap.Report(exception);
        }
    }

